// Refresh updates all windows displaying this Menu.
//
// Since: 2.5
func (m *Menu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	for _, window := range app.Driver().AllWindows() {
		if mainMenu := window.MainMenu(); mainMenu != nil {
			for _, menu := range mainMenu.Items {
				if menu == m {
					window.Canvas().Refresh(window.Content())
					break
				}
			}
		}
	}
}

// MenuItem is a single item within any menu, it contains a display Label and Action function that is called when tapped.
type MenuItem struct {
	ChildMenu *Menu
