// Refresh updates all windows displaying this Menu.
//
// Since: 2.5
func (m *Menu) Refresh() {
	app := CurrentApp()
	if app == nil {
		return
	}

	for _, window := range app.Driver().AllWindows() {
		if mainMenu := window.MainMenu(); mainMenu != nil {
			for _, menu := range mainMenu.Items {
				if menu == m {
					window.Canvas().Refresh(window.Content())
					break
				}
			}
		}
	}
}

// MenuItem is a single item within any menu, it contains a display Label and Action function that is called when tapped.
type MenuItem struct {
	ChildMenu *Menu
	// Since: 2.1
	IsQuit      bool
	IsSeparator bool
	Label       string
	Action      func()
	// Since: 2.1
	Disabled bool
	// Since: 2.1
	Checked bool
	// Since: 2.5
	Icon Resource
	// Since: 2.5
	Shortcut Shortcut
}

// NewMenuItem creates a new menu item from the passed label and action parameters.
func NewMenuItem(label string, action func()) *MenuItem {
	return &MenuItem{Label: label, Action: action}
}

